import random, re
from boltons.strutils import parse_int_list

def old(range_string, delim=',', range_delim='-'):
    output = []
    for x in range_string.strip().split(delim):
        if range_delim in x:
            rl = list(map(int, x.split(range_delim)))
            output += list(range(min(rl), max(rl)+1))
        elif not x:
            continue
        else:
            output.append(int(x))
    return sorted(output)

random.seed(7)
mismatch = 0
for _ in range(20000):
    tokens = []
    for _ in range(random.randint(0, 5)):
        kind = random.random()
        if kind < 0.35:
            tokens.append(str(random.randint(0, 30)))
        elif kind < 0.7:
            a, b = random.randint(0, 30), random.randint(0, 30)
            tokens.append('%d-%d' % (a, b))
        elif kind < 0.85:
            tokens.append('')  # empty token
        else:
            tokens.append('')
    s = ','.join(tokens)
    if random.random() < 0.5:
        s = ' ' + s + ' '
    try:
        expect = old(s)
    except ValueError:
        continue
    got = parse_int_list(s)
    if got != expect:
        mismatch += 1
        if mismatch < 5:
            print('MISMATCH', repr(s), expect, got)
print('differential mismatches:', mismatch)

# edge probes
